def split(line):
    out, cur = [], ''
    i, n = 0, len(line)
    while i < n:
        ch = line[i]
        if ch == "'":
            j = line.find("'", i + 1)
            if j == -1:
                raise ValueError("unterminated single quote")
            cur += line[i + 1:j]
            i = j + 1
        elif ch == '"':
            j = i + 1
            while j < n:
                c = line[j]
                if c == '\\':
                    if j + 1 < n and line[j + 1] in ('"', '\\'):
                        cur += line[j + 1]
                        j += 2
                        continue
                    cur += c
                    j += 1
                elif c == '"':
                    break
                else:
                    cur += c
                    j += 1
            else:
                raise ValueError("unterminated double quote")
            i = j + 1
        elif ch == '\\':
            if i + 1 < n:
                cur += line[i + 1]
                i += 2
            else:
                cur += ch
                i += 1
        elif ch.isspace():
            if cur:
                out.append(cur)
                cur = ''
            i += 1
        else:
            cur += ch
            i += 1
    if cur:
        out.append(cur)
    return out

